fn greater_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Ensure the input vectors have the same length
    assert_eq!(a.len(), b.len(), "Input vectors must have the same length");

    // Compare elementwise and collect the results
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x >= y)
     .collect()
}